package gdscript.library

import com.intellij.openapi.project.Project
import com.intellij.openapi.vfs.VfsUtilCore
import com.intellij.openapi.vfs.VirtualFile
import com.intellij.openapi.vfs.VirtualFileManager
import java.nio.file.Path

/**
 * All the documentation XMLs are generated by us into directories whose paths are known upfront (see
 * [GdSdkPathManager]), so they are read straight from the VFS: no index and no smart mode is needed, and a plain VFS
 * refresh after generation is enough to see them.
 */
class GdSdkFilesProviderImpl(private val project: Project) : GdSdkFilesProvider {

    override fun getAllSdkFiles(): Collection<VirtualFile> {
        return getAllCoreSdkFiles() + getAllProjectDocFiles()
    }

    override fun getAllCoreSdkFiles(): Collection<VirtualFile> {
        val version = GdSdkUtil.getGodotVersion(project)
        return walkXmlFiles(GdSdkPathManager.getCoreSdkDir(version))
    }

    /**
     * The GDExtension docs and the generated singletons doc: unlike the core SDK, these are regenerated while the
     * project is open, whenever an extension is added or removed.
     */
    private fun getAllProjectDocFiles(): Collection<VirtualFile> {
        return GdSdkPathManager.getProjectDocDirs(project).flatMap { walkXmlFiles(it) }
    }

    private fun walkXmlFiles(folder: Path): List<VirtualFile> {
        val folderVf = VirtualFileManager.getInstance().findFileByNioPath(folder) ?: return emptyList()
        return walkXmlVirtualFiles(folderVf)
    }

    private fun walkXmlVirtualFiles(folder: VirtualFile): List<VirtualFile> {
        if (!folder.isValid) return emptyList()
        val result = mutableListOf<VirtualFile>()
        VfsUtilCore.iterateChildrenRecursively(folder, null) { virtualFile ->
            if (!virtualFile.isDirectory && virtualFile.extension == "xml") {
                result.add(virtualFile)
            }
            true
        }
        return result
    }
}
